// Start of a sync run: one state object that travels through the page loop.
// Streams are synced one after the other: orders, then inventory levels.
const base = $env.STORE_API_BASE;
const c = $input.first().json;
const streams = [
  { stream: 'orders', path: 'orders.json', since: c.orders_since, extra: { status: 'any' } },
  { stream: 'inventory_levels', path: 'inventory_levels.json', since: c.inventory_since, extra: {} },
].map((s) => {
  // (URLSearchParams is not available in the Code-node sandbox)
  const q = { limit: '250', ...s.extra };
  if (s.since) q.updated_at_min = new Date(s.since).toISOString();
  const qs = Object.entries(q).map(([k, v]) => `${k}=${encodeURIComponent(v)}`).join('&');
  return { stream: s.stream, since: s.since || null, firstUrl: `${base}/${s.path}?${qs}` };
});
return [{
  json: {
    streams, idx: 0, url: streams[0].firstUrl, nextUrl: null,
    attempt: 0, retries: 0, rateLimited: 0, totals: {}, startedAt: new Date().toISOString(),
  },
}];

// Decide what to do with one HTTP response: apply the page, or back off and retry.
// 429 -> wait Retry-After. 5xx / network error -> exponential backoff (1, 2, 4, 8, 16 s + jitter).
// After MAX_RETRIES failed attempts (5xx / network) or MAX_429 rate-limit answers in a row for the same page,
// the run fails and the error workflow sends an email. 429s have their own budget: they are expected, not errors.
const MAX_RETRIES = 5;
const MAX_429 = 20;
const st = $('Next request').item.json;
const r = $json;
const stream = st.streams[st.idx].stream;
const code = Number(r.statusCode || 0);

if (code === 200) {
  const link = (r.headers && r.headers.link) || '';
  const m = link.match(/<([^>]+)>;\s*rel="next"/);
  return { json: { ...st, action: 'apply', stream, payload: r.body, nextUrl: m ? m[1] : null, throttled: 0 } };
}

const detail = code ? `HTTP ${code}` : `network error: ${(r.error && (r.error.message || r.error)) || 'no response'}`;
if (code && code !== 429 && code < 500) {
  throw new Error(`Store API (${stream}) refused the request: ${detail} ${JSON.stringify(r.body || '').slice(0, 200)}`);
}
const limited = code === 429;
const attempt = st.attempt + (limited ? 0 : 1);
const throttled = (st.throttled || 0) + (limited ? 1 : 0);
if (throttled > MAX_429) {
  throw new Error(`Store API (${stream}) rate limit did not clear after ${MAX_429} waits. ` +
    'Nothing was written for this page and the cursor was not moved.');
}
if (attempt > MAX_RETRIES) {
  throw new Error(`Store API (${stream}) still failing after ${MAX_RETRIES} retries: ${detail}. ` +
    'Nothing was written for this page and the cursor was not moved.');
}
const retryAfter = Number((r.headers && r.headers['retry-after']) || 0);
const wait = limited ? Math.min(60, retryAfter || 2) : Math.min(30, 2 ** (attempt - 1)) + Math.random() * 0.5;
return {
  json: {
    ...st, action: 'retry', stream, attempt, throttled,
    retries: st.retries + (limited ? 0 : 1), rateLimited: st.rateLimited + (limited ? 1 : 0),
    waitSeconds: Math.round(wait * 10) / 10, lastError: detail,
  },
};

// After a page was committed (rows + cursor in one transaction): follow the Link header, move on to the next
// stream, or finish.
const st = $('Retry or apply?').item.json;
const res = $json.result;
const totals = { ...st.totals };
const t = totals[st.stream] || { pages: 0, received: 0, changed: 0 };
totals[st.stream] = {
  pages: t.pages + 1,
  received: t.received + res.received,
  changed: t.changed + res.changed,
  cursor: res.cursor ? res.cursor.cursor_updated_at : null,
};
const next = { ...st, totals, attempt: 0, throttled: 0 };
delete next.payload;
delete next.action;
if (st.nextUrl) return { json: { ...next, url: st.nextUrl, nextUrl: null, done: false } };
if (st.idx + 1 < st.streams.length) {
  const idx = st.idx + 1;
  return { json: { ...next, idx, url: st.streams[idx].firstUrl, nextUrl: null, done: false } };
}
return { json: { ...next, done: true } };

// Run summary (also the webhook response for "run now").
const st = $json;
const z = { pages: 0, received: 0, changed: 0, cursor: null };
return [{
  json: {
    ok: true,
    synthetic_data: true,
    source: st.source || 'mock',
    orders: st.totals.orders || z,
    inventory_levels: st.totals.inventory_levels || z,
    retries: st.retries,
    rate_limited: st.rateLimited,
    seconds: Math.round((Date.now() - new Date(st.startedAt).getTime()) / 100) / 10,
  },
}];

// Start of a Shopify sync run (STORE_SOURCE=shopify): one state object that travels through the GraphQL page loop.
// Orders first (sortKey UPDATED_AT, committed page by page), then inventory levels at the primary location
// (no sort key in the API, so all pages are collected and applied in one transaction at the end).
// The token is NOT copied into this state; the GraphQL node reads it from "Get Shopify token".
const c = $('Load cursors').first().json;
const since = (ts) => (ts ? `updated_at:>='${new Date(ts).toISOString()}'` : null);
const ORDERS = `query P8Orders($first: Int!, $after: String, $q: String) {
  orders(first: $first, after: $after, sortKey: UPDATED_AT, query: $q) {
    pageInfo { hasNextPage endCursor }
    nodes {
      id name createdAt processedAt updatedAt cancelledAt displayFinancialStatus displayFulfillmentStatus
      totalPriceSet { shopMoney { amount currencyCode } }
      lineItems(first: 50) {
        pageInfo { hasNextPage }
        nodes { id sku name quantity originalUnitPriceSet { shopMoney { amount } } }
      }
    }
  }
}`;
const INVENTORY = `query P8Inventory($first: Int!, $after: String, $q: String) {
  location {
    id
    inventoryLevels(first: $first, after: $after, query: $q) {
      pageInfo { hasNextPage endCursor }
      nodes { updatedAt quantities(names: ["available"]) { name quantity } item { id sku } }
    }
  }
}`;
const streams = [
  { stream: 'orders', query: ORDERS, first: 50, q: since(c.orders_since), since: c.orders_since || null },
  { stream: 'inventory_levels', query: INVENTORY, first: 250, q: since(c.inventory_since),
    since: c.inventory_since || null },
];
return [{
  json: {
    source: 'shopify', streams, idx: 0, after: null, buffer: [],
    attempt: 0, throttled: 0, retries: 0, rateLimited: 0, totals: {}, startedAt: new Date().toISOString(),
  },
}];

// One GraphQL Admin API answer -> what to do next, and the page mapped into the same staging shape as the mock
// store's REST pages (so p8_sync_orders_page / p8_sync_inventory_page, the cursor and idempotency stay unchanged).
//   apply  : rows ready to commit (an orders page, or all inventory pages collected)
//   next   : inventory page collected, fetch the next one
//   retry  : THROTTLED / 429 -> wait until the bucket has the points; 5xx / network -> backoff 1, 2, 4, 8, 16 s
//   reauth : 401, the cached token was rejected -> forget it and fail (the next run fetches a new one)
// Every success also reads extensions.cost.throttleStatus and asks for a pause when points run low.
const MAX_RETRIES = 5;
const MAX_THROTTLED = 20;
const st = $('Next GraphQL request').item.json;
const s = st.streams[st.idx];
const r = $json;
const code = Number(r.statusCode || 0);
const body = (r.body && typeof r.body === 'object') ? r.body : {};
const errors = Array.isArray(body.errors) ? body.errors : [];
const cost = (body.extensions && body.extensions.cost) || null;

// Seconds until the bucket holds `need` points again (+0.5 s margin), 0 if it already does.
const waitForPoints = (need) => {
  const ts = cost && cost.throttleStatus;
  if (!ts || !ts.restoreRate) return 0;
  const missing = need - ts.currentlyAvailable;
  return missing > 0 ? Math.round((missing / ts.restoreRate + 0.5) * 10) / 10 : 0;
};
const numId = (gid) => Number(String(gid).split('?')[0].split('/').pop());
const lower = (v) => (v == null ? null : String(v).toLowerCase());
const FULFILLMENT = { FULFILLED: 'fulfilled', UNFULFILLED: null, PARTIALLY_FULFILLED: 'partial' };

const mapOrder = (o) => {
  if (o.lineItems.pageInfo.hasNextPage) {
    throw new Error(`Shopify order ${o.name} has more than 50 line items; raise lineItems(first:) in ` +
      '"Start Shopify streams". Nothing was written for this page and the cursor was not moved.');
  }
  return {
    id: numId(o.id),
    name: o.name,
    created_at: o.processedAt || o.createdAt,   // the order date (backdated imports keep theirs)
    updated_at: o.updatedAt,
    cancelled_at: o.cancelledAt,
    financial_status: lower(o.displayFinancialStatus),
    fulfillment_status: o.displayFulfillmentStatus in FULFILLMENT ? FULFILLMENT[o.displayFulfillmentStatus]
      : lower(o.displayFulfillmentStatus),
    currency: o.totalPriceSet.shopMoney.currencyCode,
    total_price: o.totalPriceSet.shopMoney.amount,
    line_items: o.lineItems.nodes.map((li) => ({
      id: numId(li.id),
      sku: li.sku || '',
      title: li.name,
      quantity: li.quantity,
      price: li.originalUnitPriceSet.shopMoney.amount,
    })),
  };
};
const mapLevel = (l) => {
  const q = (l.quantities || []).find((x) => x.name === 'available');
  return { inventory_item_id: numId(l.item.id), sku: l.item.sku || '', available: q ? q.quantity : 0,
           updated_at: l.updatedAt };
};

if (code === 200 && body.data && errors.length === 0) {
  const pause = waitForPoints(cost ? cost.requestedQueryCost : 0);
  const base = { ...st, stream: s.stream, attempt: 0, throttled: 0, pauseSeconds: pause };
  if (s.stream === 'orders') {
    const conn = body.data.orders;
    return { json: { ...base, action: 'apply', payload: { orders: conn.nodes.map(mapOrder) },
                     nextAfter: conn.pageInfo.hasNextPage ? conn.pageInfo.endCursor : null } };
  }
  if (!body.data.location) throw new Error('Shopify store has no primary location (read_locations scope?)');
  const conn = body.data.location.inventoryLevels;
  const buffer = st.buffer.concat(conn.nodes.map(mapLevel));
  if (conn.pageInfo.hasNextPage) {
    return { json: { ...base, action: 'next', buffer, nextAfter: conn.pageInfo.endCursor } };
  }
  return { json: { ...base, action: 'apply', buffer: [], payload: { inventory_levels: buffer }, nextAfter: null } };
}

if (code === 401) {
  return { json: { ...st, stream: s.stream, action: 'reauth' } };
}
const throttledError = errors.some((e) => e.extensions && e.extensions.code === 'THROTTLED');
if (code === 429 || (code === 200 && throttledError)) {
  const throttled = st.throttled + 1;
  if (throttled > MAX_THROTTLED) {
    throw new Error(`Shopify (${s.stream}) still THROTTLED after ${MAX_THROTTLED} waits. ` +
      'Nothing was written for this page and the cursor was not moved.');
  }
  const retryAfter = Number((r.headers && r.headers['retry-after']) || 0);
  const need = cost ? cost.requestedQueryCost : 0;
  const wait = Math.min(60, Math.max(1, retryAfter, waitForPoints(need)));
  return { json: { ...st, stream: s.stream, action: 'retry', throttled, rateLimited: st.rateLimited + 1,
                   waitSeconds: wait, lastError: 'THROTTLED' } };
}
if (!code || code >= 500) {
  const attempt = st.attempt + 1;
  const detail = code ? `HTTP ${code}` : `network error: ${(r.error && (r.error.code || r.error.message)) || 'no response'}`;
  if (attempt > MAX_RETRIES) {
    throw new Error(`Shopify (${s.stream}) still failing after ${MAX_RETRIES} retries: ${detail}. ` +
      'Nothing was written for this page and the cursor was not moved.');
  }
  const wait = Math.min(30, 2 ** (attempt - 1)) + Math.random() * 0.5;
  return { json: { ...st, stream: s.stream, action: 'retry', attempt, retries: st.retries + 1,
                   waitSeconds: Math.round(wait * 10) / 10, lastError: detail } };
}
// Anything else is not transient: GraphQL errors (bad query, missing scope), 4xx.
const msg = errors.length ? errors.map((e) => e.message).join('; ')
  : (typeof body.errors === 'string' ? body.errors : JSON.stringify(body).slice(0, 200));
throw new Error(`Shopify (${s.stream}) refused the request: HTTP ${code}: ${String(msg).slice(0, 300)}`);

// After a page was committed (orders page, or all inventory pages in one transaction) or collected (inventory):
// follow endCursor, move on to the next stream, or finish. Passes on any pause the throttle status asked for.
const st = $('Route Shopify page').item.json;
const totals = { ...st.totals };
const t = totals[st.stream] || { pages: 0, received: 0, changed: 0, cursor: null };
if (st.action === 'apply') {
  const res = $json.result;
  totals[st.stream] = {
    pages: t.pages + 1, received: t.received + res.received, changed: t.changed + res.changed,
    cursor: res.cursor ? res.cursor.cursor_updated_at : t.cursor,
  };
} else {
  totals[st.stream] = { ...t, pages: t.pages + 1 };
}
const next = { ...st, totals, attempt: 0, throttled: 0, waitSeconds: st.pauseSeconds || 0 };
for (const k of ['payload', 'action', 'nextAfter', 'pauseSeconds', 'lastError']) delete next[k];
if (st.nextAfter) return { json: { ...next, after: st.nextAfter, done: false } };
if (st.idx + 1 < st.streams.length) {
  return { json: { ...next, idx: st.idx + 1, after: null, buffer: [], done: false } };
}
return { json: { ...next, done: true } };

// Shopify answered 401 to a cached token (revoked, app reinstalled, ...). The cache row was just deleted, so the
// next run fetches a fresh token. Fail this run so the error workflow sends an email.
throw new Error('Shopify rejected the cached access token (HTTP 401). The cached token was deleted; the next run ' +
  'fetches a new one. If this repeats, check the app installation and its scopes. Nothing was written for this ' +
  'page and the cursor was not moved.');

// Which Africa/Cairo day to export: the webhook may pass {"day": "YYYY-MM-DD"}; the schedule uses today.
const body = ($json.body && typeof $json.body === 'object') ? $json.body : {};
const day = body.day || $now.setZone('Africa/Cairo').toISODate();
if (!/^\d{4}-\d{2}-\d{2}$/.test(day)) throw new Error(`Invalid day "${day}", expected YYYY-MM-DD`);
return [{ json: { day, file: `/files/exports/orders_${day}.xlsx` } }];

const d = $('Export day').first().json;
const rows = $('Load order lines').all().filter((i) => i.json.order_id !== undefined).length;
return [{ json: { ok: true, synthetic_data: true, day: d.day, file: d.file.replace('/files/', ''), rows } }];
